    switch kind {
    case 1: return .opacity
    case 2: return .asymmetric(
        insertion: .move(edge: .trailing),
        removal: .move(edge: .leading)
    )
    case 3: return .scale.combined(with: .opacity)
    case 4: return .push(from: .trailing)
    default: return .slide
    }
}

